validationRules.errorConditionFormula:
/* The line skipped for better readability. */
AND(
    NOT(ISBLANK(QuoteId)),
    NOT(ISBLANK(OpportunityId)),
    QuoteId != Opportunity.SyncedQuoteId
)

/* The line skipped for better readability. */
AND(
    ISBLANK(PRSCO_Prescriber__c),
    OR(
        /* CORE (not Italy). The prescriber is required. */
        NOT(ISPICKVAL(TEKCO_Country__c, 'ITA')),

        /* Italy. The prescriber can be required or not, depending on the Service Contract. */
        AND(
            NOT(ISBLANK(PRSCO_Therapy__r.CUSCO_ServiceContract__c)),
            NOT(PRSCO_Therapy__r.CUSCO_ServiceContract__r.PAMIT_PrescriberNotMandatory__c)
        )
    )
)

/* The line skipped for better readability. */
AND(
    ISNEW(),
    OR(
        ISPICKVAL(PRSCO_Status__c, '004' /* Closed */ ),
        ISPICKVAL(PRSCO_Status__c, '006' /* Rejected */ ),
        ISPICKVAL(PRSCO_Status__c, '008' /* Cancelled */ )
    )
)

AND(
    RecordType.DeveloperName = 'QMECO_TechnicalQuestionnaireTemplateAnswer',
    OR(
        AND(
            ISPICKVAL(QMECO_QuestionItem__r.FWMCO_AnswerType__c, '001'),
            OR(
                NOT(ISBLANK(QMECO_UpperValueLimit__c)),
                NOT(ISBLANK(QMECO_LowerValueLimit__c))
            )
        ),
        AND(
            ISPICKVAL(QMECO_QuestionItem__r.FWMCO_AnswerType__c, '002'),
            OR(
                ISBLANK(QMECO_UpperValueLimit__c),
                ISBLANK(QMECO_LowerValueLimit__c)
            )
        )
    )
)

/* The line skipped for better readability. */
AND(
    ISCHANGED(Status),

    /* Not any of allowed Status changes. */
    NOT(
        OR(
            AND(
                ISPICKVAL(PRIORVALUE(Status), '001' /* Draft */),
                ISPICKVAL(Status, '002' /* In Review */)
            ),
            AND(
                ISPICKVAL(PRIORVALUE(Status), '001' /* Draft  */),
                ISPICKVAL(Status, '003' /* Approved */),
                TEKCO_QuoteapprovalLevel__c <=  TEKCO_UserApprovalLevel__c
            ),
            AND(
                ISPICKVAL(PRIORVALUE(Status), '002' /* In Review */),
                ISPICKVAL(Status, '001' /* Draft */)
            ),
            AND(
                ISPICKVAL(PRIORVALUE(Status), '002' /* In Review */),
                ISPICKVAL(Status, '003' /* Approved */)
            ),
            AND(
                ISPICKVAL(PRIORVALUE(Status), '003' /* Approved */),
                ISPICKVAL(Status, '004' /* Presented */)
            ),
            AND(
                ISPICKVAL(PRIORVALUE(Status), '004' /* Presented */),
                ISPICKVAL(Status, '005' /* Accepted */)
            ),
            AND(
                ISPICKVAL(PRIORVALUE(Status), '004' /* Presented */),
                ISPICKVAL(Status, '006' /* Denied */)
            )
        )
    )
)

/* The line skipped for better readability. */
AND(
    ISNEW(),
    NOT(ISPICKVAL(Status, '001' /* Draft */)),
    NOT (ISPICKVAL(TEKCO_Country__c, "CAN"))
)

/* The line skipped for better readability. */
AND (
    NOT($Permission.CUSCO_AllowToSelectAutomaticTaskTypes),
    OR(
        ISPICKVAL(Type, '008'),
        ISPICKVAL(Type, '010')
    )
)

